import argparse

class KeyValue(argparse.Action):
    """Collect --set KEY=VALUE pairs into a dict."""
    def __call__(self, parser, namespace, values, option_string=None):
        if "=" not in values:
            parser.error(f"{option_string} expects KEY=VALUE, got {values!r}")
        key, value = values.split("=", 1)
        current = dict(getattr(namespace, self.dest) or {})   # copy, don't mutate default
        current[key] = value
        setattr(namespace, self.dest, current)

p = argparse.ArgumentParser(prog="deploy")
p.add_argument("--set", action=KeyValue, metavar="KEY=VALUE", default={})
a = p.parse_args(["--set", "region=eu", "--set", "replicas=3"])
print(a.set)                            # {'region': 'eu', 'replicas': '3'}
print(p.parse_args([]).set)             # {}
try:
    p.parse_args(["--set", "oops"])
except SystemExit:
    pass
# deploy: error: --set expects KEY=VALUE, got 'oops'
